{"packet_id":"D083-01","doc_id":"D083","jurisdiction":"San Francisco, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"San Francisco Rent Ordinance relocation payments for no-fault evictions (2026-2027)","requirement":"Landlords who evict under no-fault just cause (owner move-in, demolition, capital improvement, substantial rehabilitation) must pay relocation: $8,245 per tenant, max $24,733 per unit, plus $5,497 for elderly/disabled/minor-child households (3/1/26–2/28/27). Ellis Act evictions: $11,110.05 per tenant, max $33,330.13 per unit.","key_value":"$8,245.00 per tenant; max $24,733.00 per unit (3/1/26–2/28/27)","coverage_conditions":"Evictions based on owner/relative move-in, demolition/permanent removal, temporary capital improvement work, or substantial rehabilitation; and Ellis Act evictions.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":null},"exemptions":null,"penalty":null,"effective_date":"2026-03-01","citation":"S.F. Admin. Code ch. 37","quoted_span":"3/01/26 – 2/28/27\n$8,245.00\n$24,733.00\n$5,497.00","interaction":"Temporary displacement under 20 days is governed by Cal. Civ. Code § 1947.9, not Rent Ordinance § 37.9C.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
